from taf.ul.kpi_selector.operations.operation_prototype.operation_prototype import OperationPrototype
from taf.ul.kpi_selector.utilities.kpi_logger import log_suppression


class ResetCu(OperationPrototype):
    def __init__(self, bts):
        super(ResetCu, self).__init__(bts)
        self.operation_details = {
            "Timeout": 0,
            "Operation": "Capacity module reset",
            "Start point": "First cell down",
            "End point": "Last cell up",
            "Requirement": "-",
        }

    def get_kpi(self):
        """
        Gets kpi for reset cu operation.
        :return: dictionary with timeout, requirement and operation description for reset cu
        :rtype: dict
        """
        if any(
            [
                "ABIO" in self.bts.bbmod_hw_types,
                "ABIN" in self.bts.bbmod_hw_types,
                "ABIP" in self.bts.bbmod_hw_types,
                "ABIC" in self.bts.bbmod_hw_types,
                "ABIL" in self.bts.bbmod_hw_types,
                "ABIQ" in self.bts.bbmod_hw_types,
            ]
        ):
            self.operation_details["Timeout"] += 270 + self.restrictions.use_restrictions_from_OM_GEN_SFS_PERF_CAP_10517()
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.10587"

        elif any(
            [
                any(
                    [bbmod_sw_type[:2] == "FB" for bbmod_sw_type in self.bts.bbmod_hw_types]  # noqa: C419
                ),
                "ABIA" in self.bts.bbmod_hw_types,
            ]
        ):
            self.operation_details["Timeout"] += 180 + self.restrictions.use_restrictions_from_OM_GEN_SFS_PERF_CAP_10517()
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.10587"

        else:
            log_suppression("There was no configuration found in Gates tool for Your setup, "
                            "returning default timeout for reset cu. Please, do not base Your pronto "
                            "on that value.")

            self.operation_details["Timeout"] += 300

        return self.operation_details
